    "注意任何对西地那非或类似化合物的个人过敏或敏感性。",
    "患有持续医疗状况的个人应寻求持照专业人员的指导。",
    "不要与未经验证的补充剂或具有未知相互作用的物质混合。",
    "及时向医疗保健提供者报告任何异常的身体反应。",
    "服用心脏病或血压药物的人应接受医疗监督。",
    "切勿超过认证医学专家认为适合您健康档案的量。",
