    "在平静、安全的环境中使用该产品。",
    "除非医疗专业人员指示，否则请勿一次服用多片。",
    "如果片剂看起来损坏或异常，请立即停止使用。",
    "仔细遵循所有时间和给药说明。",
    "在使用期间避免使用未经验证的草药或替代补充剂。",
    "如果这是您第一次使用他达拉非，请咨询医生。",
    "将片剂储存在远离热源和湿气的阴凉干燥处。",
    "在服用每剂之前检查片剂的外观。",
