    "避免饮酒，因为它可能会增加头晕或降低耐受性。",
    "24 小时内不要超过一片。",
    "如果视力或听力突然发生变化，请立即寻求医疗帮助。",
    "本产品不适用于儿童或未经授权的用户。",
