    "其效果取决于自然的性唤起；它不会诱发自发勃起。",
    "药片在肝脏中代谢并经粪便和尿液排泄，之后残留影响极小。",
    "Zhewitra 10 支持安全的性能力，而不改变睾酮水平或长期荷尔蒙平衡。",
